parameters.jsCode:
const videoMeta = $input.item.json;
const files = videoMeta.files || {};

const formattedTags = Array.isArray(videoMeta.hashtags) 
  ? videoMeta.hashtags.join(' ') 
  : '#whisprs #poetry #quotes #deepthoughts #reels #solitude';

const captionFull = `${videoMeta.hook}\n\n"${videoMeta.script}"\n\nFollow @Whisprs for quiet reminders and late-night thoughts. 🖤\n\n${formattedTags}`;

// Structured payload ready for Zapier Webhooks & Social Automation
const zapierPayload = {
  event: 'NEW_WHISPRS_VIDEO',
  video_id: videoMeta.video_id,
  title: videoMeta.title,
  hook: videoMeta.hook,
  caption: captionFull,
  hashtags: formattedTags,
  duration_seconds: videoMeta.duration_seconds,
  stream_url: `http://localhost:5055/stream/${videoMeta.video_id}.mp4`,
  thumbnail_url: `http://localhost:5055/stream/${videoMeta.video_id}_thumb.jpg`,
  local_file_path: files.video_mp4,
  platforms: ['facebook_reels', 'youtube_shorts', 'instagram_reels', 'tiktok'],
  timestamp: new Date().toISOString()
};

return {
  json: {
    success: true,
    video_id: videoMeta.video_id,
    title: videoMeta.title,
    duration_seconds: videoMeta.duration_seconds,
    stream_url: `http://localhost:5055/stream/${videoMeta.video_id}.mp4`,
    local_file: files.video_mp4,
    desktop_file: files.desktop_mp4,
    caption: captionFull,
    zapier_payload: zapierPayload,
    status: 'READY_FOR_ZAPIER_PUBLISHING'
  },
  binary: $input.item.binary
};
